using System;using System.Linq;using System.Reflection;using TownOfHost;using TownOfHost.Modules;using Hazel;
partial class Program {
 class VisualDummy:CustomNetObject {public void Visual(string name){var m=typeof(CustomNetObject).GetMethod("SetVisualName",BindingFlags.Instance|BindingFlags.NonPublic);if(m==null)SetAppearance(0,displayName:name);else try{m.Invoke(this,new object[]{name});}catch(TargetInvocationException e){throw e.InnerException;}}}
 static void NovaOutfitTests(){
 Test("visual update never reads or overwrites original host name fields",()=>{var o=PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default];var d=new VisualDummy{PlayerControl=new()};d.Visual("star");Check(o.NameReads==0&&o.NameWrites==0&&o.RawName=="original");Check(ReferenceEquals(o,PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default]));Check(d.PlayerControl.Shapeshifts==0);});
 Test("invalid managed native-name getter does not participate in visual serialization",()=>{var o=PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default];o.ThrowNameRead=true;var d=new VisualDummy{PlayerControl=new()};d.Visual("beam");Check(o.NameReads==0&&o.RawName=="original"&&AmongUsClient.Sends==1);});
 Test("visual wire order remains temporary info shapeshift original info",()=>{var d=new VisualDummy{PlayerControl=new()};d.Visual("beam");var trace=AmongUsClient.Packets.Single();int a=Array.IndexOf(trace,"outfit:beam"),b=Array.IndexOf(trace,"write:Byte:46"),c=Array.IndexOf(trace,"outfit:original");Check(a>=0&&b>a&&c>b&&trace.Count(x=>x=="start:5")==1);});
 Test("failed visual serialization restores exact original native outfit object",()=>{var o=PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default];MessageWriter.ThrowSerialize=true;try{new VisualDummy{PlayerControl=new()}.Visual("beam");}catch{}Check(ReferenceEquals(o,PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default])&&o.RawName=="original"&&o.NameWrites==0&&AmongUsClient.Sends==0&&MessageWriter.Created.All(w=>w.Recycles==1));});
 Test("visual transport failure leaves original host state intact",()=>{var o=PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default];AmongUsClient.ThrowSend=true;try{new VisualDummy{PlayerControl=new()}.Visual("beam");}catch{}Check(ReferenceEquals(o,PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default])&&o.NameWrites==0&&MessageWriter.Created.All(w=>w.Recycles==1));});
 Test("native outfit decode failure sends nothing and returns temporary buffers",()=>{MessageReader.Created.Clear();NetworkedPlayerInfo.PlayerOutfit.ThrowDeserialize=true;try{try{new VisualDummy{PlayerControl=new()}.Visual("beam");}catch{}Check(AmongUsClient.Sends==0&&MessageWriter.Created.All(w=>w.Recycles==1)&&MessageReader.Created.All(r=>r.Recycles==1));}finally{NetworkedPlayerInfo.PlayerOutfit.ThrowDeserialize=false;}});
 Test("missing native default outfit sends no visual transaction",()=>{PlayerControl.LocalPlayer.Data.Outfits.Clear();try{new VisualDummy{PlayerControl=new()}.Visual("beam");}catch{}Check(AmongUsClient.Sends==0&&MessageWriter.Created.All(w=>w.Recycles==1));});
 Test("original-info serialization failure cannot send a half-built transaction",()=>{var data=PlayerControl.LocalPlayer.Data;var o=data.Outfits[PlayerOutfitType.Default];data.ThrowOnSerializeCall=2;try{new VisualDummy{PlayerControl=new()}.Visual("beam");}catch{}Check(ReferenceEquals(o,data.Outfits[PlayerOutfitType.Default])&&o.NameWrites==0&&AmongUsClient.Sends==0&&MessageWriter.Created.All(w=>w.Recycles==1));});
 Test("repeated visuals preserve host identity without borrowed-field writes",()=>{var o=PlayerControl.LocalPlayer.Data.Outfits[PlayerOutfitType.Default];var d=new VisualDummy{PlayerControl=new()};for(int i=0;i<100;i++)d.Visual(i%2==0?"star":"");Check(o.NameReads==0&&o.NameWrites==0&&o.RawName=="original"&&AmongUsClient.Sends==100&&MessageWriter.Created.All(w=>w.Recycles==1));});
 }
}
